parameters.jsCode:
const body = $input.first().json.body || $input.first().json || {};
const insumosCriticos = body.insumos_criticos || [];
const topProductos = body.top_productos || [];

const prompt = `
Eres el barista principal y gerente de inventario de Komorebi Café & Bakery.
Insumos críticos detectados:
${JSON.stringify(insumosCriticos, null, 2)}

Productos más vendidos:
${JSON.stringify(topProductos, null, 2)}

Genera un dictamen y sugerencia de compras para cada insumo con justificación operativa.
`;

return { prompt, insumosCriticos, topProductos };

parameters.responseBody:
={
  "ok": true,
  "data": {
    "fecha_analisis": $now.toISO(),
    "resumen_ejecutivo": $json.output || "Análisis de inventario completado por AI Agent",
    "analisis_ia": $json.output || "El modelo evaluó el déficit de insumos y el ritmo de consumo.",
    "recomendaciones": $("Preparar Datos").first().json.insumosCriticos.map(item => ({
      "insumo_id": item.id,
      "nombre": item.nombre,
      "unidad": item.unidad,
      "stock_actual": item.stock_actual,
      "stock_minimo": item.stock_minimo,
      "cantidad_sugerida": Math.round((item.deficit + item.stock_minimo * 1.5) * 100) / 100,
      "urgencia": item.stock_actual <= item.stock_minimo * 0.4 ? "Crítica" : "Alta",
      "justificacion": `El stock de ${item.nombre} está bajo mínimos. Se recomienda reponer para cubrir 7 días de consumo proyectado.`
    }))
  },
  "error": null,
  "fuente": "n8n_live_agent"
}
